_lang = "en"
_fr: dict = {}


def set_lang(code: str) -> None:
    global _lang, _fr
    _lang = "fr" if code == "fr" else "en"
    if _lang == "fr" and not _fr:
        pass
        _fr = FR


def lang() -> str:
    return _lang


def tr(text: str, **kw) -> str:
    out = _fr.get(text, text) if _lang == "fr" else text
    return out.format(**kw) if kw else out


