        live = self.ctx.econ.live
        line = hbox(spacing=6)
        ga = Button(tr("New giveaway"), "primary", 32, icon="gift")
        ga.clicked.connect(self._new_giveaway)
        sale = Button(tr("New special sale"), "primary", 32)
